<script setup>
import { computed, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'

const { t, locale } = useI18n()
const showLangMenu = ref(false)
const openFaq = ref(0)
const githubUrl = 'https://github.com/ogrre/lettredemotivation-ext'
const chromeUrl = 'https://chromewebstore.google.com/detail/lettre-de-motivation/dcopgcgecodhonbgmbiceieglcikjgli?hl=fr'
const faqs = computed(() => [
  { question: t('faq.q1.question'), answer: t('faq.q1.answer') },
  { question: t('faq.q2.question'), answer: t('faq.q2.answer') },
  { question: t('faq.q3.question'), answer: t('faq.q3.answer') },
  { question: t('faq.q4.question'), answer: t('faq.q4.answer') },
  { question: t('faq.q5.question'), answer: t('faq.q5.answer') },
  { question: t('faq.q6.question'), answer: t('faq.q6.answer') },
])
const setLanguage = lang => { locale.value = lang; showLangMenu.value = false; globalThis.localStorage?.setItem('lettre-locale', lang) }
const savedLocale = globalThis.localStorage?.getItem('lettre-locale')
if (savedLocale === 'fr' || savedLocale === 'en') locale.value = savedLocale
watch(locale, value => globalThis.document?.documentElement.setAttribute('lang', value), { immediate: true })
</script>

